const sharp = require\('sharp'\);
const fs = require\('fs'\);
const path = require\('path'\);

const dirs = [
  '/Users/onoway/my-company-site/public/tenshoku',
  '/Users/onoway/my-company-site/public/images/works'
];

function findImages\(dir\) {
  let results = [];
  for \(const entry of fs.readdirSync\(dir, { withFileTypes: true }\)\) {
    const full = path.join\(dir, entry.name\);
    if \(entry.isDirectory\(\)\) results.push\(...findImages\(full\)\);
    else if \(/\\.\(png|jpg|jpeg\)$/i.test\(entry.name\)\) results.push\(full\);
  }
  return results;
}

const files = dirs.flatMap\(findImages\);
console.log\('Found ' + files.length + ' files\\n'\);

Promise.all\(files.map\(async f => {
  const output = f.replace\(/\\.\(png|jpg|jpeg\)$/i, '.webp'\);
  const info = await sharp\(f\).webp\({ quality: 80 }\).toFile\(output\);
  const origSize = fs.statSync\(f\).size;
  const rel = f.replace\('/Users/onoway/my-company-site/public/', ''\);
  console.log\(rel + ' | ' + \(origSize/1024\).toFixed\(0\) + 'KB -> ' + \(info.size/1024\).toFixed\(0\) + 'KB | -' + \(\(1 - info.size/origSize\)*100\).toFixed\(0\) + '%'\);
}\)\).then\(\(\) => console.log\('\\nDone'\)\);
")
